draw((-0.1 - 0.03, x + w)--(-0.1 + 0.03, x + w));
draw((-0.1 - 0.03, w)--(-0.1 + 0.03, w));
label("$x$", midpoint((-0.1, w)--(-0.1, x + w)), W);

